Definition CredV (g1 : eghost) (i : nat) (E1 : env) (cr1 : credit) : Prop :=
  PPS.bufcred L cr1 (PB.cap_of G.BLS i E1) (KXg g1 (PB.tl_of G.BLS i E1)) (BXg g1 (PB.tl_of G.BLS i E1)).
Lemma CRED_EQ : forall g1 i E1 cr1, CredV g1 i E1 cr1 <-> PPS.bufcred L cr1 (PB.cap_of G.BLS i E1) (KXg g1 (PB.tl_of G.BLS i E1)) (BXg g1 (PB.tl_of G.BLS i E1)).
Proof. intros. reflexivity.
Qed.
Lemma cred_of_blocks : forall g1 i E1 cr1 ps1, CH2.den E1 (nth i G.BLS []) = PML.ps_blocks ps1 -> In (PML.ps_scap ps1) [66; 132; 264; 528; 1056] ->
  (CredV g1 i E1 cr1 <-> PML.pcredit_x L cr1 ps1 (kx + PMX.kenc L g1) (bx + PMES.benc L g1)).
Proof.
  intros g1 i E1 cr1 ps1 Hd Hs. unfold CredV, PB.cap_of, PB.tl_of, KXg, KXf, BXg. rewrite Hd. cbn [hd tl snd PML.ps_blocks].
  pose proof (PmLayout.ly_kpm L LAY) as KPM. pose proof (PmLayout.ly_bov L LAY) as BOV.
  pose proof (KENC0 g1) as K0. pose proof (EncKit_u5.EK.benc_nonneg L KPM BOV g1) as B0.
  rewrite (PPS.pcredit_x_bufcred L cr1 ps1 (kx + PMX.kenc L g1) (bx + PMES.benc L g1) KPM BOV Hs ltac:(lia) ltac:(lia)).
  replace (PPS.stk_kx L (PML.ps_scap ps1) + kx + PMX.kenc L g1) with (PPS.stk_kx L (PML.ps_scap ps1) + (kx + PMX.kenc L g1)) by lia.
  reflexivity.
Qed.
