Definition XJ (g1 : eghost) (i : nat) (E1 : env) (M1 : mem) : Prop :=
  match PSC.kind_of i with
  | PSC.KPre => (forall a, statw a -> M1 (Z_to_bv 64 a) = M (Z_to_bv 64 a)) /\ g1 = eg
  | PSC.KSetEc => PML.ls_ok PML.LS2 M1 /\ g1 = eg
  | PSC.KEsv => exists ps2 code g',
      PML.parser_at M1 P (PML.ps_set_win ps2 (PML.ps_win ps)) /\ PML.ps_win ps2 = Some (uv E1 (PSC.s1_of (cutn i)), e) /\ p <= uv E1 (PSC.s1_of (cutn i)) < e /\
      PML.wf_ps ps2 /\ PML.win_ok M1 LBo ps2 /\ PML.buf_bound ps2 B /\ PML.ec_at M1 E code /\ (code <> 0 -> PML.ps_more ps2 = false) /\
      PML.ls_ok g' M1 /\ (g' = g \/ (g' = PML.LS2 /\ code <> 0)) /\ (code = 0 -> PML.ps_more ps2 = true /\ PML.ps_level ps2 = level) /\
      uv E1 (EVar (PSC.ghost_of (cutn i))) = code /\ CH2.den E1 (nth i G.BLS []) = PML.ps_blocks ps2 /\ (code = 0 -> PMX.enc_sync ps2 g1)
  end.
