Definition SPUSH (i : nat) (u8 : bool) (m : nat) (c : Z) (E1 : env) (M1 : mem) : Prop :=
  exists (n : nat) (c0 : PMR.ctrl) (o0 : list Z) (b d : Z),
    NOF E1 n c /\ (n < length winb)%nat /\ PSKW.xrun cw (firstn n winb) = Some (c0, o0) /\ PMR.c_sst c0 = (if u8 then 11 else 5) /\
