Definition SIM (g1 : eghost) (i : nat) (E1 : env) (M1 : mem) : Prop :=
  match PSCW.KD i with
  | PSCW.KEntry => M1 = M      (* [comment removed for export] *)
  | PSCW.KStep sst c => SSTEP i sst c E1 M1
  | PSCW.KText => STEXT i E1 M1
  | PSCW.KPush u8 m c => SPUSH i u8 m c E1 M1
  | PSCW.KSetEc code => SERR code
  | PSCW.KEsv => SESV g1 i E1 M1
  | PSCW.KDead => False
  | PSCW.KBad => False
  end.
