Lemma sim_setec : forall g1 i c k ps1 j code E1 E' R' (M1 M' : mem),
  is_leaf i c k ps1 (CC.TOther PML.PC_SET_EC) -> CH2.ret_of G.RETS i k = Some j -> nth 11 (CA.ps_reglist ps1) (ELit 0) = ELit code ->
  env_agree GT.NF E0 E' -> env_agree (CC.cp_nx c) E1 E' -> CC.leaf_facts (hl_segs L) c ps1 E' R' M1 M' -> SIM g1 i E1 M1 ->
  forall E2 M2, SIM g1 j E2 M2.
Proof.
  intros g1 i c k ps1 j code E1 E' R' M1 M' qL qR q11 qA0 qA qF qS E2 M2.
  pose proof (PSCR.wl_at _ _ _ _ _ qL) as qW.
  destruct (PSCR.rb_setec _ _ _ _ qW (sim_not_dead _ _ _ _ qS)) as (code' & j' & sst & cc & q11' & qc & qR' & qKj & qst & qhas & qall).
  rewrite q11 in q11'. injection q11' as qe. subst code'.
  rewrite qR in qR'. injection qR' as qe. subst j'.
  unfold SIM. rewrite qKj. cbv beta iota. unfold SERR.
  destruct (sim_stepping _ _ _ _ _ _ qst qS) as (n & c0 & o0 & qN & qn & qX & qsst & _ & _ & _ & qcc).
  assert (qK : know_ok RSEGS E' M' (SR.ps_cells ps1)).
  { unfold know_ok. apply Forall_forall. intros K0 qK0. rewrite <- LS. exact (CC.lf_cells _ _ _ _ _ _ _ qF K0 qK0). }
  assert (qEV : forall E x, edenot E (EVar x) = ev E x) by reflexivity.
  assert (qnx : (105 <= CC.cp_nx c)%nat).
  { pose proof (PSCR.stepping_nx _ _ _ qst) as qx. destruct qL as (tags & q1 & _). unfold PSCW.cutn in qx.
    assert (qc0 : nth i PSCW.G.CPS CA.dummy_cp = c) by (apply nth_error_nth; exact q1). rewrite qc0 in qx. exact qx. }
  assert (q53 : uv E1 (EVar 53) = uv E' (EVar 53)).
  { unfold PB.uv. rewrite !qEV. rewrite (proj1 qA 53%nat) by lia. reflexivity. }
  unfold NOF in qN. rewrite q53 in qN.
  destruct (leaf_byte _ _ _ _ _ _ qK qA0 qhas qN qn qcc) as (qlt & qb & qbr).
  assert (qadm : RLF.byte_adm (PSCW.BV i) (SR.ps_cells ps1) (nth n winb 0) = true).
  { apply (RLF.byte_adm_sound RSEGS _ E' M'); [exact qK|]. rewrite <- qb. unfold PB.uv. rewrite qEV. rewrite Z_to_bv_bv_unsigned. reflexivity. }
  pose proof (PSCR.allb_sound _ _ _ _ qall qbr qadm) as qd. cbv beta in qd.
  pose proof (PSKW.sdesc_sound c0 (nth n winb 0)) as qs. rewrite qsst in qs.
  destruct (PSKW.sdesc sst (nth n winb 0)) as [s' u1 u2 out | e0 | | d | d | ]; try discriminate.
  apply Z.eqb_eq in qd. subst e0.
  destruct qs as (qx & qf).
  destruct (qf (skipn (S n) winb)) as (c' & qc').
  exists c', (nth n winb 0 :: skipn (S n) winb). split; [|exact qc].
  rewrite <- (firstn_skipn n winb) at 1. rewrite (PSKW.xrun_parse _ _ _ _ _ qX).
  rewrite (PSKW.skipn_nth_cons n winb qlt). rewrite PSKW.parse_string_cons. rewrite qx. exact qc'.
Qed.
