(* [comment removed for export] *)
Lemma cpl_keep : forall i c j s E1 E' c0 c1 sstj,
  PSCW.cutn i = c -> env_agree (CC.cp_nx c) E1 E' -> (1 <= j <= 13)%nat -> PSCR.bufkind (PSCW.KD i) = true ->
  CPL i E1 c0 -> PMR.c_sst c1 = sstj ->
  (PSCW.keep_ok (PSCW.CPX i) 58 (PSCW.sub s 58) sstj = true /\ (3 <= sstj <= 11 -> PMR.c_cp c1 mod 2 ^ 32 = PMR.c_cp c0 mod 2 ^ 32 /\ 3 <= PMR.c_sst c0 <= 11))
  \/ (3 <= sstj <= 11 -> uv E' (PSCW.sub s 58) mod 2 ^ 32 = PMR.c_cp c1 mod 2 ^ 32) ->
  (PSCW.keep_ok (PSCW.CP2X i) 59 (PSCW.sub s 59) sstj = true /\ (9 <= sstj <= 11 -> PMR.c_cp2 c1 mod 2 ^ 32 = PMR.c_cp2 c0 mod 2 ^ 32 /\ 9 <= PMR.c_sst c0 <= 11))
