(* [comment removed for export] *)
Lemma sim_goto_step : forall g1 i c k ps1 j s E1 R1 E' R' (M1 M' : mem) sst cc,
  is_leaf i c k ps1 (CC.TGoto j s) -> CC.At RSEGS c E1 R1 M1 -> env_agree GT.NF E0 E1 -> env_agree (CC.cp_nx c) E1 E' -> CC.leaf_facts RSEGS c ps1 E' R' M1 M' ->
  (1 <= j <= 13)%nat -> PSCW.KD i = PSCW.KStep sst cc -> SSTEP i sst cc E1 M1 -> PSCR.goto_stepP i sst cc (SR.ps_cells ps1) j s ->
  SIM g1 j (CC.env_over GT.NF s E') M'.
Proof.
  intros g1 i c k ps1 j s E1 R1 E' R' M1 M' sst cc qL qAt qA0 qA qF qj qKi qS qG.
  assert (qNF : GT.NF = 53%nat) by (vm_compute; reflexivity).
  assert (qc : PSCW.cutn i = c).
  { destruct qL as (tags & q1 & _). unfold PSCW.cutn. apply nth_error_nth. exact q1. }
  assert (qnx : (105 <= CC.cp_nx c)%nat) by (rewrite <- qc; exact (PSCR.stepping_nx i sst cc (or_introl qKi))).
  assert (qi1 : i <> 1%nat).
  { intros qe. subst i. assert (qK1 : PSCW.KD 1 = PSCW.KText) by (vm_compute; reflexivity). rewrite qK1 in qKi. discriminate qKi. }
  assert (qbk : PSCR.bufkind (PSCW.KD i) = true) by (rewrite qKi; reflexivity).
  pose proof (PSCR.kstep_c_range _ _ _ qKi) as qccr.
  assert (qK : know_ok RSEGS E' M' (SR.ps_cells ps1)).
  { unfold know_ok. apply Forall_forall. intros K0 qK0. exact (CC.lf_cells _ _ _ _ _ _ _ qF K0 qK0). }
  assert (qEV : forall E x, edenot E (EVar x) = ev E x) by reflexivity.
  assert (qAg : forall x, (x < 105)%nat -> uv E1 (EVar x) = uv E' (EVar x)).
  { intros x qx. unfold PB.uv. rewrite !qEV. rewrite (proj1 qA x) by lia. reflexivity. }
  assert (qA0' : env_agree GT.NF E0 E').
  { split.
    - intros x qx. rewrite (proj1 qA0 x qx). apply (proj1 qA). rewrite qNF in qx. lia.
    - rewrite (proj2 qA0). exact (proj2 qA). }
  assert (qlw : Z.of_nat (length winb) = wlen) by exact (proj2 Hwinb).
  destruct qS as (n & c0 & o0 & qN & qn & qX & qsst & qCPL & qBUF & qTAG).
  assert (qNu : Z.of_nat n = wlen - uv E1 (EVar 53) + cc) by exact qN.
  assert (qN' : Z.of_nat n = wlen - uv E' (EVar 53) + cc) by (rewrite <- qAg by lia; exact qN).
  destruct qG as (dj & cj & sstj & qdj & q53 & qcj & qsj & qtag & qbuf & qKj & qcase).
  pose proof (tgt_tagl i c k ps1 j s E1 E' qL qA qj qbk qtag qTAG) as qTAG'.
  pose proof (tgt_bufl i c k ps1 j s E1 R1 E' R' M1 M' o0 qL qAt qA qF qj qbk qbuf qBUF) as qBUF'.
  destruct qcase as [(qd0 & qss & qk58 & qk59 & _) | (qd1 & qhas & qall)].
  - destruct qKj as [(qKj & [(qi2 & q62) | (qe1 & _)]) | (qKj & _)]; [ | exfalso; exact (qi1 qe1) | ].
    + subst i. assert (qK2 : PSCW.KD 2 = PSCW.KStep 0 0) by (vm_compute; reflexivity).
      rewrite qK2 in qKi. injection qKi as qs0 qc0. subst sst cc.
      rewrite qKj in qcj, qsj. cbv [PSCW.ck_c PSCW.ck_sst] in qcj, qsj. injection qcj as qcj. injection qsj as qsj. subst cj sstj.
      apply (mk_stext g1 j _ M' n n c0 o0 qKj).
      * apply (tgt_nof s E1 E' (CC.cp_nx c) n n 0 0 dj qN q53 qdj); [intros; lia | lia | exact qA | lia].
      * rewrite uv_over_v by (rewrite qNF; lia). rewrite q62.
        change PSCW.SBO0 with (EAlu ALU_ADD (EVar 32) (EMd M_MUL (ELit (-1)) (EVar 53))).
        rewrite PSBT.uv_add, PSBT.uv_mul, PSBT.uv_lit.
        rewrite Z.mul_mod_idemp_l, Z.add_mod_idemp_r by lia.
        rewrite <- (qAg 32%nat), <- (qAg 53%nat) by lia.
        assert (q32 : uv E1 (EVar 32) = wlen).
        { destruct UU as (_ & _ & _ & _ & _ & qw & _). unfold PB.uv. rewrite qEV. rewrite <- (proj1 qA0 32%nat) by (rewrite qNF; lia). exact qw. }
        pose proof (PSBT.uv_range E1 (EVar 32)) as qr32. pose proof (PSBT.uv_range E1 (EVar 53)) as qr53.
        rewrite q32 in qr32 |- *. rewrite Z.mod_small; lia.
      * lia.
      * exact qX.
      * exact qsst.
      * rewrite Nat.sub_diag. reflexivity.
      * exact qBUF'.
      * exact qTAG'.
    + pose proof (PSCR.kstep_c_range _ _ _ qKj) as qcjr.
      apply (mk_sstep g1 j _ M' sstj cj n c0 o0 qKj).
      * apply (tgt_nof s E1 E' (CC.cp_nx c) n n cc cj dj qN q53 qdj); [intros; lia | lia | exact qA | lia].
      * exact qn.
      * exact qX.
      * rewrite qss. exact qsst.
      * apply (cpl_keep i c j s E1 E' c0 c0 sstj qc qA qj qbk qCPL (eq_trans qsst (eq_sym qss))).
        -- left. split; [exact qk58 | intros qr; split; [reflexivity | lia]].
        -- left. split; [exact qk59 | intros qr; split; [reflexivity | lia]].
      * exact qBUF'.
      * exact qTAG'.
  - destruct (leaf_byte E' M' (SR.ps_cells ps1) cc (PSCW.BV i) n qK qA0' qhas qN' qn qccr) as (qlt & qb & qbr).
    assert (qadm : RLF.byte_adm (PSCW.BV i) (SR.ps_cells ps1) (nth n winb 0) = true).
    { apply (RLF.byte_adm_sound RSEGS _ E' M'); [exact qK|]. rewrite <- qb. unfold PB.uv. rewrite qEV. rewrite Z_to_bv_bv_unsigned. reflexivity. }
    pose proof (PSCR.allb_sound _ _ _ _ qall qbr qadm) as qv. cbv beta in qv.
    pose proof (PSKW.sdesc_sound c0 (nth n winb 0)) as qs. rewrite qsst in qs.
    destruct qKj as [(qKj & [(qi2 & q62) | (qe1 & _)]) | (qKj & _)]; [ | exfalso; exact (qi1 qe1) | ].
    + subst i. assert (qK2 : PSCW.KD 2 = PSCW.KStep 0 0) by (vm_compute; reflexivity).
      rewrite qK2 in qKi. injection qKi as qs0 qc0. subst sst cc.
      rewrite qKj in qsj. cbv [PSCW.ck_sst] in qsj. injection qsj as qsj. subst sstj.
      exfalso. destruct (PSKW.sdesc 0 (nth n winb 0)) as [s' u1 u2 out | e0 | | d | d | ] eqn:qd; cbv beta iota in qv; try discriminate qv.
      * apply andb_prop in qv as (qv & _). apply andb_prop in qv as (qv & _). apply andb_prop in qv as (qa & qlb).
        apply Z.eqb_eq in qa. subst s'.
        destruct (PSCR.sdesc_text _ _ _ _ _ qd) as (_ & _ & [(qe & _) | (_ & qo & _)]).
        -- cbv [PMR.SS_ESC] in qe. discriminate qe.
        -- subst out. cbn in qlb. discriminate qlb.
      * destruct (PSCR.sdesc_su4 _ _ _ qd) as (qe & _). cbv [PMR.SS_U4] in qe. discriminate qe.
      * destruct (PSCR.sdesc_su8 _ _ _ qd) as (qe & _). cbv [PMR.SS_U8] in qe. discriminate qe.
    + pose proof (PSCR.kstep_c_range _ _ _ qKj) as qcjr.
      assert (qfin : forall c1, PSKW.xstep c0 (nth n winb 0) = Some (c1, []) -> PMR.c_sst c1 = sstj ->
        CPL j (CC.env_over GT.NF s E') c1 -> SIM g1 j (CC.env_over GT.NF s E') M').
      { intros c1 qx1 qs1 qcpl. apply (mk_sstep g1 j _ M' sstj cj (S n) c1 o0 qKj).
        - apply (tgt_nof s E1 E' (CC.cp_nx c) n (S n) cc cj dj qN q53 qdj); [intros; lia | lia | exact qA | lia].
        - lia.
        - rewrite (PSKW.firstn_succ winb n qlt). pose proof (PSKW.xrun_snoc _ _ _ _ _ _ _ qX qx1) as qq. rewrite app_nil_r in qq. exact qq.
        - exact qs1.
        - exact qcpl.
        - exact qBUF'.
        - exact qTAG'. }
      destruct (PSKW.sdesc sst (nth n winb 0)) as [s' u1 u2 out | e0 | | d | d | ] eqn:qd; cbv beta iota zeta in qv, qs; try discriminate qv.
      * apply andb_prop in qv as (qv & q59). apply andb_prop in qv as (qv & q58). apply andb_prop in qv as (qa & qlb).
        apply Z.eqb_eq in qa. subst s'.
        rewrite (proj2 (Nat.eqb_neq i 1) qi1) in qlb. destruct out as [|o1 out]; [|cbn in qlb; discriminate qlb].
        destruct qs as (c1 & qx1 & qs1 & qcp1 & qcp2).
        apply (qfin c1 qx1 qs1).
        apply (cpl_keep i c j s E1 E' c0 c1 sstj qc qA qj qbk qCPL qs1).
        -- destruct u1 as [|v|dd]; cbv [PSCW.upd_ok] in q58.
           ++ left. split; [exact q58|]. intros qr. split; [rewrite qcp1; reflexivity|]. rewrite qsst. exact (PSCR.sdesc_keep58 _ _ _ _ _ qd qr).
           ++ right. intros qr. rewrite qcp1. cbn [PSKW.appu]. apply orb_prop in q58 as [q58|q58].
              ** apply expr_eqb_eq in q58. rewrite q58, PSBT.uv_lit. apply PSBT.mod32_of_64.
              ** apply andb_prop in q58 as (qbv & q58). apply Nat.eqb_eq in qbv.
                 assert (qb111 : uv E' (PSCW.V 111) = nth n winb 0) by (rewrite <- qbv; exact qb).
                 destruct (PSCW.hexclass (nth n winb 0)) as [q|] eqn:qh; cbv beta iota in q58; [|discriminate q58].
                 apply andb_prop in q58 as (qe & qvv). apply expr_eqb_eq in qe. apply Z.eqb_eq in qvv.
                 rewrite qe, (PSCR.lin_form_val E' q (PSCW.V 111) _ qh qb111), qvv. reflexivity.
           ++ right. intros qr. rewrite qcp1. cbn [PSKW.appu].
              apply andb_prop in q58 as (qbv & q58). apply Nat.eqb_eq in qbv.
              assert (qb111 : uv E' (PSCW.V 111) = nth n winb 0) by (rewrite <- qbv; exact qb).
              destruct (PSCW.hexclass (nth n winb 0)) as [q|] eqn:qh; cbv beta iota in q58; [|discriminate q58].
              apply andb_prop in q58 as (q58 & qdd). apply andb_prop in q58 as (qo & qe).
              apply PSCR.oeqb_some in qo. apply expr_eqb_eq in qe. apply Z.eqb_eq in qdd.
              assert (qr0 : 3 <= PMR.c_sst c0 <= 11) by (rewrite qsst; exact (PSCR.sdesc_hex58 _ _ _ _ _ _ qd)).
              assert (qm : uv E' (PSCW.V 58) mod 2 ^ 32 = PMR.c_cp c0 mod 2 ^ 32).
              { change (PSCW.V 58) with (EVar 58). rewrite <- (qAg 58%nat) by lia. exact ((proj1 qCPL) qr0 _ qo). }
              rewrite qe, (PSCR.hex_form_mod E' q (PSCW.V 58) (PSCW.V 111) _ (PMR.c_cp c0) qh qb111 qm).
              rewrite Z.mod_small by apply PSCR.hexv_range. rewrite qdd. reflexivity.
        -- destruct u2 as [|v|dd]; cbv [PSCW.upd_ok] in q59.
           ++ left. split; [exact q59|]. intros qr. split; [rewrite qcp2; reflexivity|]. rewrite qsst. exact (PSCR.sdesc_keep59 _ _ _ _ _ qd qr).
           ++ right. intros qr. rewrite qcp2. cbn [PSKW.appu]. apply orb_prop in q59 as [q59|q59].
              ** apply expr_eqb_eq in q59. rewrite q59, PSBT.uv_lit. apply PSBT.mod32_of_64.
              ** apply andb_prop in q59 as (qbv & q59). apply Nat.eqb_eq in qbv.
                 assert (qb111 : uv E' (PSCW.V 111) = nth n winb 0) by (rewrite <- qbv; exact qb).
                 destruct (PSCW.hexclass (nth n winb 0)) as [q|] eqn:qh; cbv beta iota in q59; [|discriminate q59].
                 apply andb_prop in q59 as (qe & qvv). apply expr_eqb_eq in qe. apply Z.eqb_eq in qvv.
                 rewrite qe, (PSCR.lin_form_val E' q (PSCW.V 111) _ qh qb111), qvv. reflexivity.
           ++ right. intros qr. rewrite qcp2. cbn [PSKW.appu].
              apply andb_prop in q59 as (qbv & q59). apply Nat.eqb_eq in qbv.
              assert (qb111 : uv E' (PSCW.V 111) = nth n winb 0) by (rewrite <- qbv; exact qb).
              destruct (PSCW.hexclass (nth n winb 0)) as [q|] eqn:qh; cbv beta iota in q59; [|discriminate q59].
              apply andb_prop in q59 as (q59 & qdd). apply andb_prop in q59 as (qo & qe).
              apply PSCR.oeqb_some in qo. apply expr_eqb_eq in qe. apply Z.eqb_eq in qdd.
              assert (qr0 : 9 <= PMR.c_sst c0 <= 11) by (rewrite qsst; exact (PSCR.sdesc_hex59 _ _ _ _ _ _ qd)).
              assert (qm : uv E' (PSCW.V 59) mod 2 ^ 32 = PMR.c_cp2 c0 mod 2 ^ 32).
              { change (PSCW.V 59) with (EVar 59). rewrite <- (qAg 59%nat) by lia. exact ((proj2 qCPL) qr0 _ qo). }
              rewrite qe, (PSCR.hex_form_mod E' q (PSCW.V 59) (PSCW.V 111) _ (PMR.c_cp2 c0) qh qb111 qm).
              rewrite Z.mod_small by apply PSCR.hexv_range. rewrite qdd. reflexivity.
      * destruct (PSCR.sdesc_su4 _ _ _ qd) as (qs5 & _). cbv [PMR.SS_U4] in qs5.
        destruct (PSCW.hexclass (nth n winb 0)) as [q|] eqn:qh; cbv beta iota in qv; [|discriminate qv].
        apply andb_prop in qv as (qv & q59). apply andb_prop in qv as (qv & qe). apply andb_prop in qv as (qv & qo).
        apply andb_prop in qv as (qv & ql). apply andb_prop in qv as (qv & qdd). apply andb_prop in qv as (q85 & qsp).
        unfold PSCW.b85 in q85. apply Nat.eqb_eq in q85.
        apply Z.eqb_eq in qsp. cbv [PMR.SS_SP1] in qsp.
        apply Z.eqb_eq in qdd. apply PSCR.oeqb_some in qo. apply expr_eqb_eq in qe.
        assert (qb111 : uv E' (PSCW.V 111) = nth n winb 0) by (rewrite <- q85; exact qb).
        assert (qr0 : 3 <= PMR.c_sst c0 <= 11) by lia.
        assert (qm : uv E' (PSCW.V 58) mod 2 ^ 32 = PMR.c_cp c0 mod 2 ^ 32).
        { change (PSCW.V 58) with (EVar 58). rewrite <- (qAg 58%nat) by lia. exact ((proj1 qCPL) qr0 _ qo). }
        destruct (PSCR.h4_val E' q _ _ qh qb111 qm) as (qA4 & _). rewrite <- qdd in qA4.
        destruct (PSCW.lit (SR.ps_cells ps1) (PSCW.fe_hs (PSCW.A4 q))) as [[|]|] eqn:qlit; cbv beta iota in ql; try discriminate ql.
        pose proof (PSCR.lit_sound E' M' _ _ _ qK qlit) as ql1. cbv beta iota in ql1.
        assert (qhs : uv E' (PSCW.fe_hs (PSCW.A4 q)) = if PSKW.hexv (PMR.c_cp c0) d / 1024 =? 54 then 1 else 0)
          by exact (PSBT.f_hs E' (PSCW.A4 q) _ qA4 (PSCR.hexv_range _ _)).
        rewrite ql1 in qhs.
        assert (qhi : PMR.is_high_surr (PSKW.hexv (PMR.c_cp c0) d) = true).
        { rewrite PSCR.is_high_surr_div. destruct (PSKW.hexv (PMR.c_cp c0) d / 1024 =? 54); [reflexivity | discriminate qhs]. }
        destruct (proj1 qs qhi) as (c1 & qx1 & qs1 & qcp1 & qcp2).
        assert (qs1' : PMR.c_sst c1 = sstj) by (rewrite qs1; cbv [PMR.SS_SP1]; lia).
        apply (qfin c1 qx1 qs1').
        apply (cpl_keep i c j s E1 E' c0 c1 sstj qc qA qj qbk qCPL qs1').
        -- right. intros _. rewrite qe, qcp1, qA4. apply PSBT.sx32_mod.
        -- left. split; [exact q59 | intros qr; exfalso; lia].
      * apply andb_prop in qv as (q85 & qv). unfold PSCW.b85 in q85. apply Nat.eqb_eq in q85.
        assert (qb111 : uv E' (PSCW.V 111) = nth n winb 0) by (rewrite <- q85; exact qb).
        destruct (PSCW.hexclass (nth n winb 0)) as [q|] eqn:qh; cbv beta iota in qv; [|discriminate qv].
        destruct (PSCW.reg8 (SR.ps_cells ps1) q) as [rr|] eqn:qrr; cbv beta iota in qv; [|discriminate qv].
        rewrite (PSCR.reg8_r4 E' M' _ q _ rr qK qh qb111 qrr) in qv. vm_compute in qv. discriminate qv.
Qed.

(* [comment removed for export] *)
Lemma sim_goto_push : forall g1 i c k ps1 j s E1 R1 E' R' (M1 M' : mem) m cc,
  is_leaf i c k ps1 (CC.TGoto j s) -> CC.At RSEGS c E1 R1 M1 -> env_agree GT.NF E0 E1 -> env_agree (CC.cp_nx c) E1 E' -> CC.leaf_facts RSEGS c ps1 E' R' M1 M' ->
  (1 <= j <= 13)%nat -> PSCW.KD i = PSCW.KPush true m cc -> SPUSH i true m cc E1 M1 ->
  let cells := SR.ps_cells ps1 in
  j = 2%nat -> PSCW.sub s 53 = PSCW.JM1 -> PSCW.hasb cells cc (PSCW.BV i) = true -> PSCW.b85 i = true ->
  PSCW.allb (PSCW.admlist cells (PSCW.BV i)) (fun b => match PSCW.hexclass b with Some q => match PSCW.reg8 cells q with Some PSCW.R4 => Nat.eqb m 4 | _ => false end | None => false end) = true ->
  PSCW.tag_ok i (PSCW.sub s 60) = true -> PSCW.buf_ok i (PSCW.sub s 55) (PSCW.sub s 56) = true ->
  SIM g1 j (CC.env_over GT.NF s E') M'.
Proof.
  intros g1 i c k ps1 j s E1 R1 E' R' M1 M' m cc qL qAt qA0 qA qF qj qKi qS.
  cbv zeta. intros qj2 q53 qhas q85 qall qtag qbuf.
  subst j.
  assert (qc : PSCW.cutn i = c).
  { destruct qL as (tags & q1 & _). unfold PSCW.cutn. apply nth_error_nth. exact q1. }
  assert (qnx : (105 <= CC.cp_nx c)%nat) by (rewrite <- qc; exact (PSCR.push_nx _ _ _ _ qKi)).
  pose proof (PSCR.kpush_c_range _ _ _ _ qKi) as qcc0. subst cc.
  assert (qbk : PSCR.bufkind (PSCW.KD i) = true) by (rewrite qKi; reflexivity).
  assert (qK : know_ok RSEGS E' M' (SR.ps_cells ps1)).
  { unfold know_ok. apply Forall_forall. intros K0 qK0. exact (CC.lf_cells _ _ _ _ _ _ _ qF K0 qK0). }
  assert (qEV : forall E x, edenot E (EVar x) = ev E x) by reflexivity.
  assert (qNF : GT.NF = 53%nat) by (vm_compute; reflexivity).
  assert (qAg : forall y, (y < 105)%nat -> uv E1 (EVar y) = uv E' (EVar y)).
  { intros y qy. unfold PB.uv. rewrite !qEV. rewrite (proj1 qA y) by lia. reflexivity. }
  assert (qA0' : env_agree GT.NF E0 E').
  { split.
    - intros y qy. rewrite (proj1 qA0 y qy). apply (proj1 qA). rewrite qNF in qy. lia.
    - rewrite (proj2 qA0). exact (proj2 qA). }
  assert (qlw : Z.of_nat (length winb) = wlen) by exact (proj2 Hwinb).
  destruct qS as (n & c0 & o0 & b & d & qN & qn & qX & qsst & qCPV & qTAG & qnb & qb111 & qhv & _ & qm & qBUF).
  assert (qNu : Z.of_nat n = wlen - uv E1 (EVar 53) + 0) by exact qN.
  assert (qN' : Z.of_nat n = wlen - uv E' (EVar 53) + 0) by (rewrite <- qAg by lia; exact qNu).
  destruct (leaf_byte E' M' (SR.ps_cells ps1) 0 (PSCW.BV i) n qK qA0' qhas qN' (Nat.lt_le_incl _ _ qn) ltac:(lia)) as (_ & qb & qbr).
  assert (qadm : RLF.byte_adm (PSCW.BV i) (SR.ps_cells ps1) (nth n winb 0) = true).
  { apply (RLF.byte_adm_sound RSEGS _ E' M'); [exact qK|]. rewrite <- qb. unfold PB.uv. rewrite qEV. rewrite Z_to_bv_bv_unsigned. reflexivity. }
  pose proof (PSCR.allb_sound _ _ _ _ qall qbr qadm) as qv. cbv beta in qv.
  rewrite qnb in qv.
  destruct (PSCR.hexval_class _ _ qhv) as (q & qh & _). rewrite qh in qv. cbv beta iota in qv.
  destruct (PSCW.reg8 (SR.ps_cells ps1) q) as [[ | | | | | ]|]; try discriminate qv.
  apply Nat.eqb_eq in qv. subst m.
  assert (qsst' : PMR.c_sst c0 = 11) by exact qsst.
  assert (qsd : PSKW.sdesc 11 b = PSKW.SU8 d) by (unfold PSKW.sdesc; rewrite qhv; reflexivity).
  pose proof (PSKW.sdesc_sound c0 b) as qs. rewrite qsst', qsd in qs. cbv beta iota zeta in qs.
  destruct qs as (c1 & qx1 & qs1 & _ & _).
  assert (qs1' : PMR.c_sst c1 = 0) by exact qs1.
  assert (qlen : length (PMR.utf8_of (XOF true c0 d)) = 4%nat).
  { pose proof (PSCR.utf8_of_len (XOF true c0 d)). lia. }
  rewrite (firstn_all2 (n := 4%nat) (PMR.utf8_of (XOF true c0 d))) in qBUF by lia.
  assert (qKj : PSCW.KD 2 = PSCW.KStep 0 0) by (vm_compute; reflexivity).
  apply (mk_sstep g1 2 _ M' 0 0 (S n) c1 (o0 ++ PMR.utf8_of (XOF true c0 d)) qKj).
  - apply (tgt_nof s E1 E' (CC.cp_nx c) n (S n) 0 0 1 qN); [exact q53 | right; reflexivity | intros _; lia | lia | exact qA | lia].
  - lia.
  - rewrite (PSKW.firstn_succ winb n qn). rewrite qnb. exact (PSKW.xrun_snoc _ _ _ _ _ _ _ qX qx1).
  - exact qs1'.
  - unfold CPL. rewrite qs1'. split; intros qr; exfalso; lia.
  - exact (tgt_bufl i c k ps1 2 s E1 R1 E' R' M1 M' _ qL qAt qA qF qj qbk qbuf qBUF).
  - exact (tgt_tagl i c k ps1 2 s E1 E' qL qA qj qbk qtag qTAG).
Qed.

