(* [comment removed for export] *)
Lemma buf_ident : forall i c E1 (M1 : mem) E' R' ps1 (M' : mem) pe ce se pl o (s : list Z) cap pp,
  PSCW.cutn i = c -> PSCR.blk0 i = Some (pe, ce) -> PSCR.cutwP i -> PSCR.bufleaf_chk i (SR.ps_cells ps1) = true ->
  env_agree GT.NF E0 E' -> env_agree (CC.cp_nx c) E1 E' -> CC.leaf_facts RSEGS c ps1 E' R' M1 M' -> know_ok RSEGS E' M' (SR.ps_cells ps1) ->
  PSCW.cellv (SR.ps_cells ps1) 232 8 = Some se -> PSCW.cellv (SR.ps_cells ps1) 240 8 = Some pl ->
  Forall PSKW.inb o -> BUFL i E1 M1 o -> PML.str_at M' (P + 224) (PML.SLong cap pp s) -> Z.of_nat (length s) < 2 ^ 64 ->
