Lemma firstn_S_nth : forall (l : list Z) (m : nat), (m < length l)%nat -> firstn (S m) l = firstn m l ++ [nth m l 0].
Proof. ltac2:(Rpl.RP.run_i (rplG ()) 0 "S00$l;R!1+^4+A$m;R+\$~R!2'g8#1!2'^P+A#2!3'nY#3#2#1").
Qed.
(* [comment removed for export] *)
Lemma sim_push : forall g1 i c k ps1 j cj E1 E' R' (M1 M' : mem) E2 (M2 : mem) (s : list Z) (cv pp cap p' cap' : Z) (nx : nat),
  is_leaf i c k ps1 (CC.TOther PML.PC_STR_PUSH_BACK) -> CH2.ret_of G.RETS i k = Some j -> nth_error G.CPS j = Some cj ->
  env_agree GT.NF E0 E' -> env_agree (CC.cp_nx c) E1 E' -> CC.leaf_facts (hl_segs L) c ps1 E' R' M1 M' -> SIM g1 i E1 M1 ->
  PML.str_at M' (P + 224) (PML.SLong cap pp s) -> cv = uv E' (nth 11 (CA.ps_reglist ps1) (ELit 0)) -> PML.str_at M2 (P + 224) (PML.SLong cap' p' (s ++ [cv])) ->
