(* [comment removed for export] *)
Lemma sim_app : forall g1 i c k ps1 j cj E1 E' R' (M1 M' : mem) E2 (M2 : mem) (s src : list Z) (q pp cap p' cap' : Z) (nx : nat),
  is_leaf i c k ps1 (CC.TOther PML.PC_STR_APPEND) -> CH2.ret_of G.RETS i k = Some j -> nth_error G.CPS j = Some cj ->
  env_agree GT.NF E0 E' -> env_agree (CC.cp_nx c) E1 E' -> CC.leaf_facts (hl_segs L) c ps1 E' R' M1 M' -> SIM g1 i E1 M1 ->
  PML.str_at M' (P + 224) (PML.SLong cap pp s) -> q = uv E' (nth 11 (CA.ps_reglist ps1) (ELit 0)) -> Z.of_nat (length src) = uv E' (nth 12 (CA.ps_reglist ps1) (ELit 0)) ->
  L5.bytes_at RSEGS M' q src -> PML.str_at M2 (P + 224) (PML.SLong cap' p' (s ++ src)) ->
