Lemma esv_pre_r8 : forall g1 i c k ps1 E1 E' R' (M1 M' : mem),
  is_leaf i c k ps1 (CC.TOther PML.PC_END_STRING) -> env_agree GT.NF E0 E' -> env_agree (CC.cp_nx c) E1 E' -> CC.leaf_facts (hl_segs L) c ps1 E' R' M1 M' -> SIM g1 i E1 M1 ->
  let cells := SR.ps_cells ps1 in let regs := CA.ps_reglist ps1 in
  exists j (n : nat) c0 o0, CH2.ret_of G.RETS i k = Some j /\ PSCW.KD j = PSCW.KEsv /\ nth 8 regs (ELit 0) = PSCW.CUR0 /\ uv E' PSCW.CUR0 = p + Z.of_nat n /\
    Z.of_nat n = wlen - uv E' (EVar 53) /\ (n < length winb)%nat /\ nth n winb 0 = 34 /\ PSKW.xrun cw (firstn n winb) = Some (c0, o0) /\ PMR.c_sst c0 = 0 /\
    PSKW.core_eq cw c0 /\ PSKW.tok_ok c0 (BUFB o0) /\ Forall PSKW.inb o0 /\
    PMR.parse_string cw winb = PMR.end_string c0 (skipn n winb) /\
    L5.bytes_at RSEGS M' (uv E' (nth 11 regs (ELit 0))) (BUFB o0) /\ uv E' (nth 12 regs (ELit 0)) = Z.of_nat (length (BUFB o0)) /\
    (exists t, PML.u8 M' (P + 220) t /\ 0 <= t <= 1) /\ PB.has cells (KBlob (SA (EVar 11) 0) (EVar 32) 1) = true.
