Lemma esv_r21 : forall i c k ps1, is_leaf i c k ps1 (CC.TOther PML.PC_END_STRING) ->
  nth 21 (CA.ps_reglist ps1) (ELit 0) = nth 8 (CA.ps_reglist ps1) (ELit 0).
Proof.
  intros i c k ps1 IL.
  assert (OK : CH2.leaves_all G.CPS G.TAGS (fun (_ : nat) (_ : CC.cutpoint) (_ : nat) (ps : SR.post_spec) (t : CC.tag) =>
    match t with
    | CC.TOther pc => if Z.eqb pc PML.PC_END_STRING then expr_eqb (nth 21 (CA.ps_reglist ps) (ELit 0)) (nth 8 (CA.ps_reglist ps) (ELit 0)) else true
    | _ => true
    end) = true) by (vm_compute; reflexivity).
  pose proof (CH2.leaves_all_sound _ _ _ OK _ _ _ _ _ IL) as X.
  cbv beta iota in X. rewrite Z.eqb_refl in X.
  apply expr_eqb_eq. exact X.
Qed.
Lemma esv_pre : forall g1 i c k ps1 E1 E' R' (M1 M' : mem),
  is_leaf i c k ps1 (CC.TOther PML.PC_END_STRING) -> env_agree GT.NF E0 E' -> env_agree (CC.cp_nx c) E1 E' -> CC.leaf_facts (hl_segs L) c ps1 E' R' M1 M' -> SIM g1 i E1 M1 ->
  let cells := SR.ps_cells ps1 in let regs := CA.ps_reglist ps1 in
  exists j (n : nat) c0 o0, CH2.ret_of G.RETS i k = Some j /\ PSCW.KD j = PSCW.KEsv /\ nth 21 regs (ELit 0) = PSCW.CUR0 /\ uv E' PSCW.CUR0 = p + Z.of_nat n /\
    Z.of_nat n = wlen - uv E' (EVar 53) /\ (n < length winb)%nat /\ nth n winb 0 = 34 /\ PSKW.xrun cw (firstn n winb) = Some (c0, o0) /\ PMR.c_sst c0 = 0 /\
    PSKW.core_eq cw c0 /\ PSKW.tok_ok c0 (BUFB o0) /\ Forall PSKW.inb o0 /\
    PMR.parse_string cw winb = PMR.end_string c0 (skipn n winb) /\
    L5.bytes_at RSEGS M' (uv E' (nth 11 regs (ELit 0))) (BUFB o0) /\ uv E' (nth 12 regs (ELit 0)) = Z.of_nat (length (BUFB o0)) /\
    (exists t, PML.u8 M' (P + 220) t /\ 0 <= t <= 1) /\ PB.has cells (KBlob (SA (EVar 11) 0) (EVar 32) 1) = true.
Proof.
  intros g1 i c k ps1 E1 E' R' M1 M' IL qA0 qA qF qS cells regs.
  pose proof (esv_pre_r8 g1 i c k ps1 E1 E' R' M1 M' IL qA0 qA qF qS) as X. cbv zeta in X.
  destruct X as (j & n & c0 & o0 & q1 & q2 & q3 & q4).
  exists j, n, c0, o0. split; [exact q1|]. split; [exact q2|]. split; [|exact q4].
  change (nth 21 (CA.ps_reglist ps1) (ELit 0) = PSCW.CUR0). rewrite (esv_r21 i c k ps1 IL). exact q3.
Qed.

Lemma end_string_w : forall c0 w1 w2,
  PMR.q_c (PMR.end_string c0 w1) = PMR.q_c (PMR.end_string c0 w2) /\ PMR.q_evs (PMR.end_string c0 w1) = PMR.q_evs (PMR.end_string c0 w2) /\
  PMR.q_al (PMR.end_string c0 w1) = PMR.q_al (PMR.end_string c0 w2) /\ PMR.q_code (PMR.end_string c0 w1) = PMR.q_code (PMR.end_string c0 w2).
Proof.
  intros c0 w1 w2. unfold PMR.end_string, PMR.err. cbv zeta.
  repeat match goal with |- context [if ?b then _ else _] => destruct b end; repeat split; reflexivity.
Qed.
Lemma of_text_tok : forall c0 x, PSKW.tok_ok c0 x -> PMR.b256 x = x -> PMR.of_text c0 x = c0.
Proof. intros c0 x [HD HU] HB. unfold PMR.of_text, PMR.set_tok. rewrite HB, <- HU, <- HD. destruct c0; reflexivity. Qed.
Lemma esv_room : forall (g1 : eghost) (n : nat) c0 x,
  PMR.parse_string cw winb = PMR.end_string c0 (skipn n winb) -> PSKW.tok_ok c0 x -> PMR.b256 x = x ->
  PMW.wroomrU PMR.the_rm g1 (PMW.rm_step PMR.the_rm PMW.FParseString cw winb) ->
  PMW.wroomrU PMR.the_rm g1 (PMW.rm_step PMR.the_rm PMW.FEndStringValue c0 x).
Proof.
  intros g1 n c0 x HPS HT HB.
  unfold PMW.wroomrU. cbn [PMW.rm_step PMR.the_rm PMR.rstep PMR.r_of PMR.r_of0 PMW.r_evs PMW.r_allow].
  rewrite HPS, (of_text_tok c0 x HT HB). destruct (end_string_w c0 (skipn n winb) []) as (_ & E1 & E2 & _). rewrite E1, E2. exact (fun H => H).
Qed.
Lemma PAR_def : L5.defined M P 272.
Proof.
  pose proof PAR as X.
  repeat match type of X with _ /\ _ => destruct X as [_ X] end.
  exact X.
Qed.

Lemma sr_vars_nth : forall nx regs k, APC.sr_vars_lt nx regs = true -> APC.expr_vars_lt nx (nth k regs (ELit 0)) = true.
Proof.
  intros nx regs. induction regs as [|x0 r0 IH]; intros k H; destruct k as [|k]; cbn [nth APC.sr_vars_lt] in H |- *; try reflexivity.
  - apply andb_prop in H as [H _]. exact H.
  - apply andb_prop in H as [_ H]. exact (IH k H).
Qed.
Lemma krange_uv : forall E' (M' : mem) cells x lo hi, know_ok RSEGS E' M' cells -> PB.prove cells (KRange x lo hi) = true -> lo <= uv E' x <= hi.
Proof. intros E' M' cells x lo hi HK H. pose proof (PB.prove_ok E' M' cells _ HK H) as Y. cbn [kentry_ok] in Y. exact Y. Qed.

Lemma leaf_esv : forall i c k ps1 j cj ci, is_leaf i c k ps1 (CC.TOther PML.PC_END_STRING) -> CH2.ret_of G.RETS i k = Some j -> nth_error G.CPS j = Some cj ->
  SR.ps_pc ps1 = PML.PC_END_STRING -> PSC.kind_of i = PSC.KPre -> PSC.kind_of j = PSC.KEsv -> PSC.foot_pre_chk c = true ->
  PBX.ptrans_chkx GT.NF G.HDECL PSC.Eb 0 PSC.Pb 0 11136 PSC.Vb PML.LIT_LO 14 c ps1 cj (nth i G.BLS []) (nth j G.BLS []) = Some ci -> PSC.esv_leaf_chk i c ps1 cj = true ->
  forall g1 M0c, OKV M0c -> CH2V.leaf_okV L HI GT.NF E0 M model LBo sp G.HDECL W G.BLS eghost gB CredV XIv G.CPS K PML.fp_ok g1 M0c i c ps1.
Proof.
  intros i c k ps1 j cj ci IL Hret Hcj Hpc Ki Kj Hfoot Hchk Hesv g1 M0c HOKV.
  pose proof (fun th : option (Z * Z) * PB6W.THW PMR.the_rm => PBLWU.gbxlw_EU L HI PMR.the_rm _ _ _ _ _ _ _ _ _ _ _ (ESV_OK (fst th)) (snd th)) as CE.
  refine (PB6WU.ptrans_leaf_okxwU L HI HIok LAY GT.NF E0 M model LBo sp G.HDECL W G.BLS CredV XIv
    STKF SCRP NF32 U2 TP0 W_OK CRS_OK WRS_OK IMG_OK
    G.CPS G.TAGS G.RETS K HKnil DEF0 PSC.Eb 0 ltac:(vm_compute; reflexivity) E EADDR g HG
    PSC.Pb 0 ltac:(vm_compute; reflexivity) P PADDR V S2 OBJS WPAR_in W_ENC PSC.Vb ltac:(vm_compute; reflexivity) VADDR S2LT S2ADDR
    ltac:(vm_compute; reflexivity) PML.PC_END_STRING _ _ _ _ _ _ _ _ _ _ CE _ B kx bx Hkx Hbx
    PML.LIT_LO 14 i c k ps1 j cj ci g1 M0c eq_refl HOKV IL Hret Hcj Hpc Hchk _).
  - intros th pst0 M1 P1 ps2 [HPA2 _]. exact (pa_cap M1 P1 ps2 _ HPA2).
  - intros E1 E' R' M1 M' model1 cr1 Hag0 Hsr Hnx Hag LF HR HAV XIV HH1 HC.
    destruct XIV as (HXJ & HXN & HSIM).
    unfold XJ in HXJ. rewrite Ki in HXJ. destruct HXJ as (HST1 & ->).
    pose proof (esv_pre eg i c k ps1 E1 E' R' M1 M' IL Hag0 Hag LF HSIM) as X. cbv zeta in X.
    destruct X as (j0 & n & c0 & o0 & Q1 & Q2 & Q3 & Q4 & Q5 & Q6 & Q7 & Q8 & Q9 & Q10 & Q11 & Q12 & Q13 & Q14 & Q15 & Q16 & Q17).
    assert (j0 = j) by congruence. subst j0.
    unfold PSC.esv_leaf_chk in Hesv. cbv zeta in Hesv.
    apply andb_prop in Hesv as [Hesv HVM]. apply andb_prop in Hesv as [Hesv HS1]. apply andb_prop in Hesv as [Hesv HR14].
    apply andb_prop in Hesv as [Hesv HR13]. apply andb_prop in Hesv as [HBV HR10].
    apply expr_eqb_eq in HS1, HR14, HR13, HR10.
    destruct (PSC.view_chk 1 (SR.ps_cells ps1) (nth i G.BLS [])) as [[[pe ce] pv]|] eqn:HV; [|discriminate HVM].
    apply andb_prop in HVM as [HVM HALT]. apply andb_prop in HVM as [HVM HSZ]. apply andb_prop in HVM as [HVM HWS1].
    apply andb_prop in HVM as [HVM HS1L]. apply andb_prop in HVM as [HVM CSEG]. apply andb_prop in HVM as [CEC CVIS].
    pose proof (leaf_know c ps1 E' R' M1 M' LF) as HK.
    assert (FOOT : (PSC.foot_pre_chk c || PSC.foot_esv_chk c)%bool = true) by (rewrite Hfoot; reflexivity).
    pose proof (CC.lf_frame _ _ _ _ _ _ _ LF) as FRM.
    destruct OBJJ as ((OP1 & OP2 & _) & (OV1 & OV2 & _) & (OE1 & OE2 & _) & _).
    destruct SPF as (_ & _ & _ & (SP1 & SP2) & _).
    assert (HDP : L5.defined M' P 272).
    { apply (amb_def eg M0c HOKV i E1 M' model1 P 272 HAV PAR_def). left. lia. }
    destruct (view_sound 1 (SR.ps_cells ps1) (nth i G.BLS []) pe ce pv E' M' HV (or_intror eq_refl) HK Hag0 HDP)
      as (HBL & HSST & buf & HPA1 & HLEN & HCE & HPE & HDEF).
    destruct (FRZ E' Hag0) as (FPb & FSEG & FWEND & FBX & FSB & FSLEN & FSC & FLVL & FNST & FDONE & FEb & FVb & F2 & FST).
    set (pst := PML.PS 15 (uv E' (PB2.pv_sst pv)) nst true (PML.ps_done ps) level (PML.ps_stack ps) sb scap (uv E' ce) (uv E' pe) buf
                  (Some (p + Z.of_nat n, e))).
    assert (HDEN' : CH2.den E' (nth i G.BLS []) = PML.ps_blocks pst).
    { rewrite HBL. unfold CH2.den. cbn [map fst snd].
      fold (uv E' pe). fold (uv E' ce). fold (uv E' PSC.SBx). fold (uv E' PSC.SCAP). rewrite FSB, FSC. reflexivity. }
    assert (HDEN1 : CH2.den E1 (nth i G.BLS []) = PML.ps_blocks pst).
    { rewrite <- (CH2.den_agree (CC.cp_nx c) E1 E' (nth i G.BLS []) Hag HBV). exact HDEN'. }
    assert (HSCP : In (PML.ps_scap pst) [66; 132; 264; 528; 1056]) by (destruct HWF as (_ & _ & _ & X & _); exact X).
    assert (EADDR' : estart E' (SA PSC.Eb 0) = E) by (rewrite (PB.estart_agree GT.NF E0 E' PSC.Eb 0 Hag0 eq_refl); exact EADDR).
    assert (HSTM : forall a, statw a -> M' (Z_to_bv 64 a) = M (Z_to_bv 64 a)) by exact (xi_pre_step c E' M1 M' FOOT Hag0 FRM HST1).
    pose proof (xinv_stretch eg c E' M1 M' FOOT Hag0 FRM (gblocks_amb eg M0c i E1 M' model1 HAV) HXN) as HXN'.
    assert (WL : Z.of_nat (length winb) = e - p) by exact (proj2 Hwinb).
    pose proof HWIN as HW0. unfold PML.win_ok in HW0. rewrite Hwin in HW0. destruct HW0 as (ch & Hch & CH1 & CH2 & HDW).
    destruct (hio_wf L SCFG HI HIok _ _ _ _ HH1) as (Hwf1 & _).
    assert (INCUR : forall b0, In b0 (CH2.den E1 (nth i G.BLS []) ++ LBo) -> In b0 (CH2.cur (CH2V.LBr LBo eghost gB eg) G.BLS i E1)).
    { intros b0 Hb0. unfold CH2.cur, CH2V.LBr. rewrite app_assoc. apply in_or_app. left. exact Hb0. }
    assert (BRch : block_range L ch 16384).
    { exact (proj1 (Hwf1 (ch, 16384) (INCUR _ (in_or_app _ _ _ (or_intror Hch))))). }
    assert (BRpe : block_range L (uv E' pe) (uv E' ce)).
    { refine (proj1 (Hwf1 (uv E' pe, uv E' ce) (INCUR _ (in_or_app _ _ _ (or_introl _))))). rewrite HDEN1. left. reflexivity. }
    pose proof (pa_len M' P _ HPA1) as HBL1. cbn [PML.ps_buf PML.ps_bcap] in HBL1.
    assert (HDW' : L5.defined M' p (e - p)).
    { apply (amb_def eg M0c HOKV i E1 M' model1 p (e - p) HAV HDW). right. exists ch. split; [exact Hch|]. lia. }
    destruct STKX as (SK1 & SK2 & (SK3 & SK4) & _).
    destruct BRch as (BC0 & _ & _ & _ & BC4). destruct BRpe as (BP0 & _ & _ & BP3 & BP4).
    assert (HB26 : B < 2 ^ 26) by (destruct HBB as (_ & X); exact X).
    assert (HB0 : 0 <= B) by (pose proof (PB.uv_range E' PSC.BX) as X; rewrite FBX in X; lia).
    assert (KSZ : Z.of_nat (length buf) + (e - (p + Z.of_nat n)) <= B).
    { pose proof (krange_uv E' M' _ _ _ _ HK HSZ) as KZ. rewrite Q3 in KZ.
      rewrite PB.uv_esub, PB.uv_eadd, PB.uv_esub, FBX, FWEND, Q4, <- HLEN in KZ.
      rewrite (Z.mod_small (e - (p + Z.of_nat n))) in KZ by lia.
      rewrite (Z.mod_small (Z.of_nat (length buf) + (e - (p + Z.of_nat n)))) in KZ by lia.
      apply mod_pos in KZ; lia. }
    exists (Some (p, e), (skipn n winb, BUFB o0, c0)), pst.
    split; [exact HDEN'|].
    split.
    { unfold PB6WU.ptrans_prexU. cbv beta.
      split.
      { unfold PBLW.argsXLW. cbv beta iota.
        split.
        { split.
          { unfold PML.a0. rewrite (reg_at E' (CA.ps_reglist ps1) R' 10 10%bv HR eq_refl eq_refl), HR10. apply PB.edenot_of_uv. exact FPb. }
          split.
          { unfold PML.a3. rewrite (reg_at E' (CA.ps_reglist ps1) R' 13 13%bv HR eq_refl eq_refl), HR13. apply PB.edenot_of_uv. exact FVb. }
          split.
          { rewrite (reg_at E' (CA.ps_reglist ps1) R' 14 14%bv HR eq_refl eq_refl), HR14. apply PB.edenot_of_uv. exact FEb. }
          split; [reflexivity|]. split; [reflexivity|].
          split; [exact Q16|].
          exists (uv E' (nth 11 (CA.ps_reglist ps1) (ELit 0))), (uv E' (nth 12 (CA.ps_reglist ps1) (ELit 0))).
          split.
          { unfold PML.a1. rewrite (reg_at E' (CA.ps_reglist ps1) R' 11 11%bv HR eq_refl eq_refl). apply PB.edenot_of_uv. reflexivity. }
          split.
          { unfold PML.a2. rewrite (reg_at E' (CA.ps_reglist ps1) R' 12 12%bv HR eq_refl eq_refl). apply PB.edenot_of_uv. reflexivity. }
          rewrite Q15.
          set (sA := uv E' (nth 11 (CA.ps_reglist ps1) (ELit 0))).
          pose proof (PB.uv_range E' (nth 11 (CA.ps_reglist ps1) (ELit 0))) as SAR. fold sA in SAR.
          assert (SPAN : 0 <= Z.of_nat (length (BUFB o0)) < 2 ^ 26 /\ L5.defined M' sA (Z.of_nat (length (BUFB o0))) /\ 4096 <= sA /\
                         sA + Z.of_nat (length (BUFB o0)) <= hl_ceil L /\ PMES.in_blocks (PML.ps_blocks pst ++ LBo) sA (Z.of_nat (length (BUFB o0)))).
          { apply orb_prop in HALT as [HA|HB].
            - apply andb_prop in HA as [HA1 HA2]. apply expr_eqb_eq in HA1, HA2.
              assert (Ss : sA = uv E' pe) by (unfold sA; rewrite HA1; reflexivity).
              assert (Ln : Z.of_nat (length (BUFB o0)) = Z.of_nat (length buf)) by (rewrite <- Q15, HA2, <- HLEN; reflexivity).
              rewrite Ss, Ln.
              split; [lia|]. split; [apply (L5.defined_sub _ _ _ _ _ HDEF); lia|]. split; [lia|]. split; [lia|].
              right. exists (uv E' pe, uv E' ce). split; [apply in_or_app; left; unfold pst, PML.ps_blocks; cbn [PML.ps_bptr PML.ps_bcap]; left; reflexivity|].
              cbn [fst snd]. lia.
            - apply andb_prop in HB as [HB HB3]. apply andb_prop in HB as [HB1 HB2].
              pose proof (krange_uv E' M' _ _ _ _ HK HB1) as K1. pose proof (krange_uv E' M' _ _ _ _ HK HB2) as K2.
              pose proof (krange_uv E' M' _ _ _ _ HK HB3) as K3.
              rewrite PB.uv_esub, FSEG in K1. fold sA in K1. rewrite PB.uv_esub, PB.uv_eadd, FWEND, Q15 in K2. fold sA in K2. rewrite Q15 in K3.
              assert (PS : p <= sA).
              { destruct (Z_le_gt_dec p sA) as [Hle|Hgt]; [exact Hle|]. exfalso.
                rewrite <- (Z_mod_plus_full (sA - p) 1 (2 ^ 64)) in K1. rewrite Z.mod_small in K1 by lia. lia. }
              rewrite Z.mod_small in K1 by lia.
              rewrite (Z.mod_small (sA + Z.of_nat (length (BUFB o0)))) in K2 by lia.
              assert (SE : sA + Z.of_nat (length (BUFB o0)) <= e).
              { destruct (Z_le_gt_dec (sA + Z.of_nat (length (BUFB o0))) e) as [Hle|Hgt]; [exact Hle|]. exfalso.
                rewrite <- (Z_mod_plus_full (e - (sA + Z.of_nat (length (BUFB o0)))) 1 (2 ^ 64)) in K2. rewrite Z.mod_small in K2 by lia. lia. }
              split; [lia|]. split; [apply (L5.defined_sub _ _ _ _ _ HDW'); lia|]. split; [lia|]. split; [lia|].
              right. exists (ch, 16384). split; [apply in_or_app; right; exact Hch|]. cbn [fst snd]. lia. }
          destruct SPAN as (SP1' & SP2' & SP3' & SP4' & SP5').
          split; [exact SP1'|]. split; [exact SP2'|]. split; [exact SP3'|]. split; [exact SP4'|]. split; [exact SP5'|].
          split; [exact Q14|]. split; [reflexivity|].
          unfold BUFB. apply Forall_app. split; [exact (PSKW.b256_inb _) | exact Q12]. }
        split.
        { unfold PMW.win_bytes, pst. cbn [PML.ps_win].
          split; [exact (bytes_at_skip M' p winb n (win_at_leaf E' M' (SR.ps_cells ps1) HK Hag0 Q17))|].
          split; [rewrite length_skipn; lia|].
          rewrite Forall_forall in *. intros x Hx. apply Hwinr. rewrite <- (firstn_skipn n winb). apply in_or_app. right. exact Hx. }
        cbn [PMW.rm_stale PMR.the_rm]. unfold PMR.rm_stale, PMR.rm_core, pst. cbn [PML.ps_st PML.ps_more PML.ps_done PML.ps_level PML.ps_stack].
        destruct Q10 as (C1 & C2 & C3 & C4 & C5 & _). destruct (proj1 HRM) as (R1 & R2 & R3 & R4 & R5).
        split; [rewrite <- C1, R1, Hst; reflexivity|]. split; [rewrite <- C2, R2, Hmore; reflexivity|].
        split; [rewrite <- C3, R3; reflexivity|]. split; [rewrite <- C4, R4; reflexivity|]. rewrite <- C5, R5; reflexivity. }
      split; [exact HPA1|].
      split; [apply PML.wf_ps_stale_of; apply wf_upd; exact HSST|].
      split.
      { unfold PML.win_ok, pst. cbn [PML.ps_win]. exists ch. split; [exact Hch|]. split; [lia|]. split; [exact CH2|].
        apply (L5.defined_sub _ _ _ _ _ HDW'); lia. }
      split.
      { unfold PMS.buf_bound_stale, PML.winlen, pst. cbn [PML.ps_buf PML.ps_win]. split; [lia|]. split; [exact HB26|]. lia. }
      split.
      { unfold PML.vis_at. pose proof (PB2.kword64_elim E' M' _ _ V (PB.has_ok E' M' _ _ HK CVIS)) as X.
        replace (uv E' (ELit PML.VT_VISITOR)) with PML.VT_VISITOR in X by (unfold PB.uv; cbn [edenot]; symmetry; apply u64_of_Z; unfold PML.VT_VISITOR; lia).
        apply X. unfold estart. cbn [a_base a_off]. fold (uv E' PSC.Vb). rewrite FVb. lia. }
      split.
      { unfold PML.ec_at. split; [|split; [|left; reflexivity]].
        - pose proof (PB2.kword32_elim E' M' _ _ E (PB.has_ok E' M' _ _ HK CEC) EADDR') as X.
          replace (uv E' (ELit 0)) with 0 in X by (unfold PB.uv; cbn [edenot]; reflexivity). exact X.
        - apply (amb_def eg M0c HOKV i E1 M' model1 E 16 HAV (proj1 (proj2 HEC))). left. lia. }
      split; [exact (ls_pre eg M0c HOKV i E1 M' model1 HAV HSTM)|].
      split; [exact (proj1 HXN')|].
      split; [exact (proj2 HXN')|].
      split.
      { destruct HSYNC as [HS1' HS2']. split; [exact HS1'|]. unfold PMX.key_inv in *. unfold pst. cbn [PML.ps_more PML.ps_st PML.ps_stack PML.ps_level].
        rewrite Hmore, Hst in HS2'. exact HS2'. }
      split; [exact (proj1 (cred_of_blocks eg i E1 cr1 pst HDEN1 HSCP) HC)|].
      unfold PB6WU.roomW. cbv beta iota. unfold PMW.inp_aux.
      exact (esv_room eg n c0 (BUFB o0) Q13 Q11 (BUFB_norm o0 Q12) HROOM). }
    intros R2 M2 cr2 ps2 code g' eg' E2 POST Hag2 Hcode Hr10 Hden2 HPRES.
    unfold PB6WU.ptrans_postxU in POST. cbn [fst snd] in POST.
    destruct POST as ((PA2 & PW2) & WF2 & WO2 & BB2 & EC2 & MO2 & LS2 & GG2 & INV2 & LIT2 & SY2 & PC2 & REL2 & EX2).
    unfold PB6W.expostW in EX2. cbv beta iota zeta in EX2.
    cbn [PMW.rm_step PMR.the_rm PMR.rstep PMR.r_of0 PMW.r_code PMW.r_evs PMW.r_allow PMW.r_ctrl] in EX2. unfold PMW.inp_aux in EX2.
    rewrite (of_text_tok c0 (BUFB o0) Q11 (BUFB_norm o0 Q12)) in EX2.
    destruct (end_string_w c0 [] (skipn n winb)) as (EQc & EQe & EQa & EQd). rewrite EQc, EQe, EQa, EQd in EX2.
    destruct EX2 as (X1 & X2 & X3 & X4).
    assert (HS1E2 : uv E2 (PSC.s1_of (cutn j)) = p + Z.of_nat n).
    { rewrite (nth_cut j cj Hcj), HS1. rewrite (cells_vars_agree (CH2.ci_nx ci) E' E2 _ (sr_vars_nth _ _ 21 Hsr) Hag2). rewrite Q3. exact Q4. }
    assert (XJ2 : PML.parser_at M2 P (PML.ps_set_win ps2 (PML.ps_win ps)) /\ PML.ps_win ps2 = Some (uv E2 (PSC.s1_of (cutn j)), e) /\
                  p <= uv E2 (PSC.s1_of (cutn j)) < e /\ PML.wf_ps ps2 /\ PML.win_ok M2 LBo ps2 /\ PML.buf_bound ps2 B /\ PML.ec_at M2 E code /\
                  (code <> 0 -> PML.ps_more ps2 = false) /\ PML.ls_ok g' M2 /\ (g' = g \/ (g' = PML.LS2 /\ code <> 0)) /\
                  (code = 0 -> PML.ps_more ps2 = true /\ PML.ps_level ps2 = level) /\ uv E2 (EVar (PSC.ghost_of (cutn j))) = code /\
                  CH2.den E2 (nth j G.BLS []) = PML.ps_blocks ps2 /\ (code = 0 -> PMX.enc_sync ps2 eg')).
    { split; [rewrite Hwin; exact PA2|]. split; [rewrite PW2, HS1E2; reflexivity|]. split; [rewrite HS1E2; lia|].
      split; [exact WF2|]. split; [exact WO2|]. split; [exact BB2|]. split; [exact EC2|]. split; [exact MO2|]. split; [exact LS2|].
      split; [exact GG2|].
      split.
      { intros C0. destruct REL2 as [(_ & RM2 & RL2 & _)|HIN]; [split; [exact RM2 | exact RL2]|]. exfalso. subst code. cbn in HIN. intuition lia. }
      split.
      { rewrite (nth_cut j cj Hcj). unfold PSC.ghost_of. rewrite <- Hnx. unfold PB.uv. cbn [edenot]. exact Hcode. }
      split; [exact Hden2 | exact SY2]. }
    split.
    + split.
      { unfold XJ. rewrite Kj. exists ps2, code, g'. exact XJ2. }
      split; [split; [exact INV2 | exact LIT2]|].
      unfold SIM. rewrite Q2. unfold SESV. exists ps2, code, g', n, c0, o0.
      split; [exact XJ2|]. split; [rewrite HS1E2; lia|]. split; [exact Q6|]. split; [exact Q8|]. split; [exact Q13|].
      cbv zeta. split; [exact X1|]. split; [exact X2|]. split; [exact X3|].
      intros C0. destruct (X4 C0) as (RM2 & _). cbn [PMW.rm_match PMR.the_rm] in RM2. split; [exact (proj1 RM2)|].
      destruct REL2 as [(_ & _ & _ & HIN)|HIN]; [|exfalso; subst code; cbn in HIN; intuition lia].
      cbv [In PML.ST_EXPECT_COLON PML.ST_EXPECT_COMMA_OR_END PML.ST_ACCEPT PML.ST_STRING PML.ST_NUMBER] in HIN |- *. intuition lia.
    + destruct WF2 as (_ & _ & _ & HSC2 & _). exact (proj2 (cred_of_blocks eg' j E2 cr2 ps2 Hden2 HSC2) PC2).
Qed.


