Lemma exit_view : forall i c k ps1 ml code g' need pe ce pv,
  is_leaf i c k ps1 (CC.TOther PSC.RETPC) -> PB.exit_base_chk GT.NF PSC.RETPC c ps1 = true -> CH2.all_regs_chk ps1 = true ->
  PSC.view_chk ml (SR.ps_cells ps1) (nth i G.BLS []) = Some (pe, ce, pv) -> ml = 0 \/ ml = 1 ->
  PSC.cur_chk (SR.ps_cells ps1) (nth 10 (CA.ps_reglist ps1) (ELit 0)) (PB2.pv_size pv) need = true -> 0 <= need <= 3 ->
  (forall E', ml = 1 -> PML.esc_need (uv E' (PB2.pv_sst pv)) = need) -> (ml = 0 -> need = 0) -> (code = 0 <-> ml = 1) ->
  (code <> 0 \/ PSC.progress_chk (SR.ps_cells ps1) (nth 10 (CA.ps_reglist ps1) (ELit 0)) = true) -> (g' = g \/ (g' = PML.LS2 /\ code <> 0)) ->
  forall g1 M0c, OKV M0c -> (PSC.kind_of i = PSC.KPre \/ PSC.kind_of i = PSC.KSetEc) -> PSC.foot_pre_chk c = true ->
  (forall E1 E' R' (M1 M' : mem) model1, env_agree (CC.cp_nx c) E1 E' -> CC.leaf_facts (hl_segs L) c ps1 E' R' M1 M' -> XJ g1 i E1 M1 -> HAMBV g1 M0c i E1 M' model1 -> env_agree GT.NF E0 E' ->
      know_ok RSEGS E' M' (SR.ps_cells ps1) -> L5.defined M' E 16 -> PML.ec_at M' E code /\ PML.ls_ok g' M') ->
