Section Final.
Context {SCFG_P : ScfgP}.
Variable L : heap_layout.
Variable HI : heap_iface.
Hypothesis HIok : heap_iface_ok L SCFG HI.
Hypothesis LAY : PmLayout.pm0_layout L.
Hypothesis FPM : forall (fx fx' : FPState) R pc M R' pc' M',
  msteps RSEGS (@mkst fx R (Z_to_bv 64 pc) M (seg_rom RSEGS)) (@mkst fx' R' (Z_to_bv 64 pc') M' (seg_rom RSEGS)) -> PML.fp_ok fx -> PML.fp_ok fx'.
Hypothesis PUSHB_OK : PMS.str_push_back_spec L HI.
Hypothesis APPEND_OK : PMS.str_append_spec L HI.
Hypothesis SETEC_OK : PMS.set_ec_spec L.
Hypothesis ESV_OK : PMW.end_string_value_specwU L HI PMES.WD_SCR_X PMR.the_rm.      (* [comment removed for export] *)

Theorem parse_string_okwU : PMW.parse_string_specwU L HI PML.STRTOD_SCR_V PMES.WD_SCR_X PMR.the_rm.
Proof.
  unfold PMW.parse_string_specwU, PMW.ptrans_curxwU, PMW.ptrans_gxwU, PMW.ptrans_gbxwU. intros LBo cr sp r P V E S2 B kx bx g ps eg w x c. unfold PML.cps_heap.
  intros fx R M model K HH Hmo HKnil Hfp (Hentry & ((Ha0 & Ha2 & Ha3 & (p & e & Hwin & Ha1)) & Hmore & Hst) & HPA & HWF & HWIN & HBB & HVIS & HEC & HLS & HG & HINV & HLIT & HSYNC & Hkx & Hbx & HPC & OBJS & HWBY & HRM & HROOM) Hcont.
  pose proof (pa_def _ _ _ HPA) as HdP.
  destruct (PB2.cell_exists M (P + 148) 4 ltac:(lia)) as (cp0 & Rc0 & Hcp0); [eapply (L5.defined_sub _ _ _ _ _ HdP); cbn; lia|].
  destruct (PB2.cell_exists M (P + 152) 4 ltac:(lia)) as (cp20 & Rc20 & Hcp20); [eapply (L5.defined_sub _ _ _ _ _ HdP); cbn; lia|].
  destruct (PB2.cell_exists M (P + 168) 8 ltac:(lia)) as (pos0 & Rp0 & Hpos0); [eapply (L5.defined_sub _ _ _ _ _ HdP); cbn; lia|].
  assert (HRM' : PMR.rm_match c M P ps) by exact HRM.
  destruct (proj1 (proj2 HRM') Hst) as (_ & _ & _ & _ & _ & (esc0 & Hesc0 & Hesc01)).
  assert (Hcpr : 0 <= cp0 < 2 ^ 64 /\ 0 <= cp20 < 2 ^ 64 /\ 0 <= pos0 < 2 ^ 64 /\ 0 <= esc0 < 2 ^ 64) by lia.
  assert (HWB : L5.bytes_at RSEGS M p w /\ Z.of_nat (length w) = e - p /\ Forall (fun b => 0 <= b <= 255) w).
  { unfold PMW.win_bytes in HWBY. rewrite Hwin in HWBY. exact HWBY. }
  destruct HWB as (Hwb1 & Hwb2 & Hwinr).
  exact (main L HI HIok LAY FPM PUSHB_OK APPEND_OK SETEC_OK ESV_OK LBo cr sp r P V E S2 B kx bx g ps eg fx R M model K p e
    HH Hmo HKnil Hfp Hentry Ha0 Ha1 Ha2 Ha3 Hwin Hmore Hst HPA HWF HWIN HBB HVIS HEC HLS HG HINV HLIT HSYNC Hkx Hbx HPC OBJS
    cp0 cp20 pos0 esc0 w Hcp0 Hcp20 Hpos0 Hesc0 Hcpr (conj Hwb1 Hwb2) Hwinr c HRM' HROOM Hesc01 Hcont).
Qed.
End Final.
Print Assumptions parse_string_okwU.

